E NOT EXISTS (SELECT 1 FROM {{table.薪资发放}} WHERE {{table.薪资发放}}.{{col.薪资发放.员工号}} = {{table.员工}}.{{col.员工.员工号}})","commonMistake":"SELECT {{col.员工.姓名}} FROM {{table.员工}} WHERE EXISTS (SELECT 1 FROM {{table.薪资发放}} WHERE {{table.薪资发放}}.{{col.薪资发放.员工号}} = {{table.员工}}.{{col.员工.员工号}})","ordered":false},{"templateId":"sub-scalar-max","knowledgeArea":"子查询","difficulty":3,"prompt":"查询月薪最高的员工姓名（用标量子查询取最大值）。","hints":["思路：内层 SELECT MAX(...) 只返回一个值，外层用它做等值比较。","关键子句：WHERE {{col.员工.月薪}} = (SELECT MAX({{col.员工.月薪}}) FROM {{table.员工}})"],"referenceAnswer":"SELECT {{col.员工.姓名}} FROM {{table.员工}} WHERE {{col.员工.月薪}} = (SELECT MAX({{col.员工.月薪}}) FROM {{table.员工}})","commonMistake":"SELECT {{col.员工.姓名}} FROM {{table.员工}} WHERE {{col.员工.月薪}} = (SELECT MIN({{col.员工.月薪}}) FROM {{table.员工}})","ordered":false},{"templateId":"sub-derived","knowledgeArea":"子查询","difficulty":5,"prompt":"查询发薪达到 3 次及以上的员工各发了几次薪（从按员工号分组的派生表中筛选，列别名「次数」）。","hints":["思路：把分组统计写成 FROM 里的派生表并起别名，外层对统计结果再筛选。","关键子句：FROM (SELECT ... GROUP BY 员工号) AS t WHERE 次数 >= 3"],"referenceAnswer":"SELECT 次数 FROM (SELECT {{col.薪资发放.员工号}} AS 员工号, COUNT(*) AS 次数 FROM {{table.薪资发放}} GROUP BY {{col.薪资发放.员工号}}) AS t WHERE 次数 >= 3","commonMistake":"SELECT 次数 FROM (SELECT {{col.薪资发放.员工号}} AS 员工号, COUNT(*) AS 次数 FROM {{table.薪资发放}} GROUP BY {{col.薪资发放.员工号}}) AS t","ordered":false},{"templateId":"date-year-group","knowledgeArea":"日期函数","difficulty":3,"prompt":"按入职年份统计员工人数（列别名「入职年份」「人数」）。","hints":["思路：YEAR 函数从日期中取出年份，按它分组计数。","关键子句：GROUP BY YEAR({{col.员工.入职日期}})"],"referenceAnswer":"SELECT YEAR({{col.员工.入职日期}}) AS 入职年份, COUNT(*) AS 人数 FROM {{table.员工}} GROUP BY YEAR({{col.员工.入职日期}})","commonMistake":"SELECT MONTH({{col.员工.入职日期}}) AS 入职年份, COUNT(*) AS 人数 FROM {{table.员工}} GROUP BY MONTH({{col.员工.入职日期}})","ordered":false},{"templateId":"date-year-filter","knowledgeArea":"日期函数","difficulty":2,"prompt":"查询 2025 年发放的薪资记录，返回员工号。","hints":["思路：对日期列套 YEAR 再与 2025 比较。","关键子句：WHERE YEAR({{col.薪资发放.发放日期}}) = 2025"],"referenceAnswer":"SELECT {{col.薪资发放.员工号}} FROM {{table.薪资发放}} WHERE YEAR({{col.薪资发放.发放日期}}) = 2025","commonMistake":"SELECT {{col.薪资发放.员工号}} FROM {{table.薪资发放}} WHERE YEAR({{col.薪资发放.发放日期}}) = 2026","ordered":false},{"templateId":"date-format","knowledgeArea":"日期函数","difficulty":3,"prompt":"查询每位员工的姓名与格式化后的入职日期（格式为{{param.格式.描述}}，列别名「入职日」），按员工号升序返回。","hints":["思路：DATE_FORMAT(日期, 格式串) 按给定格式输出文本，格式串由题面描述决定。","关键子句：DATE_FORMAT({{col.员工.入职日期}}, ''{{param.格式.模式}}'')"],"referenceAnswer":"SELECT {{col.员工.姓名}}, DATE_FORMAT({{col.员工.入职日期}}, ''{{param.格式.模式}}'') AS 入职日 FROM {{table.员工}} ORDER BY {{col.员工.员工号}}","commonMistake":"SELECT {{col.员工.姓名}}, DATE_FORMAT({{col.员工.入职日期}}, ''%Y'') AS 入职日 FROM {{table.员工}} ORDER BY {{col.员工.员工号}}","ordered":true,"paramPool":{"格式":[{"描述":"「年-月-日」（如 2020-02-29）","模式":"%Y-%m-%d"},{"描述":"「月/日」（如 02/29）","模式":"%m/%d"}]}},{"templateId":"date-datediff","knowledgeArea":"日期函数","difficulty":4,"prompt":"查询薪资发放表中最早发放日期与最晚发放日期相差多少天（列别名「跨度天数」）。","hints":["思路：DATEDIFF(a, b) 求 a 减 b 的天数，先聚合出两个端点日期再作差。","关键子句：SELECT DATEDIFF(MAX({{col.薪资发放.发放日期}}), MIN({{col.薪资发放.发放日期}}))"],"referenceAnswer":"SELECT DATEDIFF(MAX({{col.薪资发放.发放日期}}), MIN({{col.薪资发放.发放日期}})) AS 跨度天数 FROM {{table.薪资发放}}","commonMistake":"SELECT DATEDIFF(MIN({{col.薪资发放.发放日期}}), MAX({{col.薪资发放.发放日期}})) AS 跨度天数 FROM {{table.薪资发放}}","ordered":false},{"templateId":"comp-order-limit","knowledgeArea":"综合应用","difficulty":4,"prompt":"查询发放金额最高的前 {{param.名额}} 条记录的员工姓名与发放金额（同额按员工号升序）。","hints":["思路：连接员工与薪资发放后，按金额降序、员工号升序排序，再 LIMIT。","关键子句：ORDER BY {{col.薪资发放.发放金额}} DESC, {{table.员工}}.{{col.员工.员工号}} LIMIT {{param.名额}}"],"referenceAnswer":"SELECT {{col.员工.姓名}}, {{col.薪资发放.发放金额}} FROM {{table.员工}} JOIN {{table.薪资发放}} ON {{table.员工}}.{{col.员工.员工号}} = {{table.薪资发放}}.{{col.薪资发放.员工号}} ORDER BY {{col.薪资发放.发放金额}} DESC, {{table.员工}}.{{col.员工.员工号}} LIMIT {{param.名额}}","commonMistake":"SELECT {{col.员工.姓名}}, {{col.薪资发放.发放金额}} FROM {{table.员工}} JOIN {{table.薪资发放}} ON {{table.员工}}.{{col.员工.员工号}} = {{table.薪资发放}}.{{col.薪资发放.员工号}} ORDER BY {{col.薪资发放.发放金额}} ASC, {{table.员工}}.{{col.员工.员工号}} LIMIT {{param.名额}}","ordered":true,"paramPool":{"名额":[3,5]}},{"templateId":"comp-case","knowledgeArea":"综合应用","difficulty":4,"prompt":"查询每条发放记录的员工号与发放状态（列别名「状态」）：发放金额为空记「未发放」，不低于 {{param.线}} 元记「高额」，否则记「普通」。","hints":["思路：CASE 多分支先判 IS NULL 再判阈值，空值与比较要分开处理。","关键子句：CASE WHEN 金额 IS NULL THEN ''未发放'' WHEN 金额 >= 阈值 THEN ''高额'' ELSE ''普通'' END"],"referenceAnswer":"SELECT {{col.薪资发放.员工号}}, CASE WHEN {{col.薪资发放.发放金额}} IS NULL THEN ''未发放'' WHEN {{col.薪资发放.发放金额}} >= {{param.线}} THEN ''高额'' ELSE ''普通'' END AS 状态 FROM {{table.薪资发放}}","commonMistake":"SELECT {{col.薪资发放.员工号}}, CASE WHEN {{col.薪资发放.发放金额}} IS NULL THEN ''未发放'' WHEN {{col.薪资发放.发放金额}} >= {{param.线}} THEN ''大额'' ELSE ''普通'' END AS 状态 FROM {{table.薪资发放}}","ordered":false,"paramPool":{"线":[12000,15000]}},{"templateId":"comp-city-having","knowledgeArea":"综合应用","difficulty":3,"prompt":"按部门所在城市统计部门个数（城市为空的不计），只保留部门数达到 2 个的城市（列别名「部门数」）。","hints":["思路：WHERE 先排除空城市，再 GROUP BY + HAVING 过滤数量。","关键子句：WHERE 城市 IS NOT NULL GROUP BY 城市 HAVING COUNT(*) >= 2"],"referenceAnswer":"SELECT {{col.部门.城市}}, COUNT(*) AS 部门数 FROM {{table.部门}} WHERE {{col.部门.城市}} IS NOT NULL GROUP BY {{col.部门.城市}} HAVING COUNT(*) >= 2","commonMistake":"SELECT {{col.部门.城市}} FROM {{table.部门}} WHERE {{col.部门.城市}} IS NOT NULL GROUP BY {{col.部门.城市}} HAVING COUNT(*) >= 2","ordered":false}],"knowledgeAreas":["单表查询与投影","条件筛选与排序","聚合与分组","多表 JOIN","子查询","日期函数","综合应用"],"difficultyTiers":[{"level":1,"name":"入门","description":"单表查询与列投影：直接从一张表取全量或指定列，不附加筛选条件","sampleSql":"SELECT {{col.员工.姓名}} FROM {{table.员工}}"},{"level":2,"name":"基础","description":"条件筛选与排序：使用 WHERE 过滤行、ORDER BY 排序，含去重与边界值比较","sampleSql":"SELECT {{col.员工.姓名}}, {{col.员工.月薪}} * 12 AS 年度薪资 FROM {{table.员工}}"},{"level":3,"name":"进阶","description":"聚合与分组：COUNT/SUM/AVG/MAX/MIN 聚合函数配合 GROUP BY/HAVING 分组统计","sampleSql":"SELECT {{col.员工.姓名}} FROM {{table.员工}} ORDER BY {{col.员工.员工号}} LIMIT {{param.名额}}"},{"level":4,"name":"综合","description":"多表 JOIN 与子查询：跨表连接取数，或以子查询嵌套表达二层条件","sampleSql":"SELECT {{col.员工.姓名}} FROM {{table.员工}} LEFT JOIN {{table.薪资发放}} ON {{table.员工}}.{{col.员工.员工号}} = {{table.薪资发放}}.{{col.薪资发放.员工号}} WHERE {{table.薪资发放}}.{{col.薪资发放.员工号}} IS NULL"},{"level":5,"name":"挑战","description":"多条件组合的综合应用：多表连接叠加聚合/子查询/排序，需处理 NULL 与极端值边界","sampleSql":"SELECT 次数 FROM (SELECT {{col.薪资发放.员工号}} AS 员工号, COUNT(*) AS 次数 FROM {{table.薪资发放}} GROUP BY {{col.薪资发放.员工号}}) AS t WHERE 次数 >= 3"}],"practiceConfig":{"totalQuestions":10,"tierDistribution":{"1":1,"2":3,"3":3,"4":2,"5":1}}}'::jsonb)
